const $=selector=>document.querySelector(selector);
function photo(id,width=900){
    if(/^\/?assets\//.test(id))return '/'+id.replace(/^\//,'').replace(/(indian-(?:budget|homestay|retreat|tent-village))\.png$/,'$1-1280.webp');
    if(id.startsWith('https:')||/^\/media\/property\/\d+$/.test(id))return id;
    return `https://images.unsplash.com/${id}?auto=format&fit=crop&w=${width}&q=85`;
}
let state={...searchDefaults},selected=properties[0],roomIndex=0,guest={},booking=null,dashTab='Overview';
let saved=JSON.parse(localStorage.getItem('mks-saved')||'[]'),ownerDrafts=JSON.parse(localStorage.getItem('mks-drafts')||'[]');
const money=n=>'₹'+n.toLocaleString('en-IN'),escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const demo='<div class="demo-banner">✧ Frontend preview · Properties and rates are illustrative. Live availability is unconfirmed. No real bookings or payments.</div>';
const brand='<a class="brand" href="#/"><span class="brand-icon">♧</span><span>Mahakumbh<b>Stays</b><small>YOUR STAY. YOUR SACRED JOURNEY.</small></span></a>';
function header(){return `<div class="topbar">A sacred journey. A stay that feels right. <span> | </span> Discover Nashik & Trimbakeshwar · Kumbh 2027</div><header><div class="container nav">${brand}<button class="mobile-toggle" aria-label="Toggle navigation" onclick="document.querySelector('.links').classList.toggle('open')">☰</button><nav class="links"><a href="#/stays">Explore stays</a><a href="#/guide">Kumbh 2027 ↗</a><a href="#/support">Help & support</a><a href="#/owner" class="btn outline small">List your property ↗</a><button onclick="login()">Sign in →</button></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div>${brand}<p class="mt">Thoughtful stays for meaningful journeys.<br>Discover your home away from home in Nashik and Trimbakeshwar.</p><span class="eyebrow">Rooted in hospitality.</span></div><div><h4>Discover</h4><a href="#/stays">Explore all stays</a><a href="#/guide">Nashik Kumbh 2027</a><a href="#/group-stays">Group bookings</a></div><div><h4>For our partners</h4><a href="#/owner">List your property</a><a href="#/hotel-partner">Hotel partner portal</a><a href="#/rental-host">Rental host dashboard</a><a href="#/admin">Admin dashboard</a></div><div><h4>We're here to help</h4><a href="#/support">Contact & support</a><a href="#/policy/privacy">Privacy policy</a><a href="#/policy/terms">Terms & conditions</a><a href="#/policy/cancellation">Cancellation policy</a></div></div><div class="footer-bottom"><span>© 2026 MahakumbhStays. Your Stay for Every Sacred Journey.</span><span>Frontend demo · No real reservations</span></div><div class="notice mt">Destination photography: <a style="display:inline" href="https://commons.wikimedia.org/wiki/File:Nasik,_Ramkund_(6362131297).jpg" target="_blank" rel="noopener">Ramkund — Arian Zwegers</a> (<a style="display:inline" href="https://creativecommons.org/licenses/by/2.0/">CC BY 2.0</a>); <a style="display:inline" href="https://commons.wikimedia.org/wiki/File:Trimbakeshwar_temple_front_view.jpg" target="_blank" rel="noopener">Trimbakeshwar Temple — Varuninaganti</a> (<a style="display:inline" href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>). Displayed with layout crops and overlays. Historical photographs; not images of the 2027 event.</div></div></footer>`}
function searchForm(){return `<form class="search" onsubmit="searchSubmit(event)"><div class="field"><label for="destination">⌾ Where are you headed?</label><select id="destination" name="destination">${['All destinations',...locations].map(l=>`<option ${state.destination===l?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label for="checkin">Check-in</label><input id="checkin" name="checkin" type="date" value="${state.checkin}" required></div><div class="field"><label for="checkout">Check-out</label><input id="checkout" name="checkout" type="date" value="${state.checkout}" required></div><div class="field"><label for="guests">Guests & rooms</label><select id="guests" name="guests">${[1,2,3,4,5,6,8].map(n=>`<option value="${n}" ${state.guests===n?'selected':''}>${n} guest${n>1?'s':''}</option>`).join('')}</select><select name="rooms" aria-label="Number of rooms">${[1,2,3,4].map(n=>`<option value="${n}" ${state.rooms===n?'selected':''}>${n} room${n>1?'s':''}</option>`).join('')}</select></div><button class="btn" type="submit">Search stays <span>↗</span></button></form>`}
function searchSubmit(e){e.preventDefault();let f=new FormData(e.target);if(f.get('checkout')<=f.get('checkin'))return toast('Choose a check-out date after check-in.');Object.assign(state,{destination:f.get('destination'),checkin:f.get('checkin'),checkout:f.get('checkout'),guests:+f.get('guests'),adults:+f.get('guests'),children:0,rooms:+f.get('rooms')});goToStays()}
function card(p){return `<article class="property"><div class="photo"><a href="#/stay/${p.id}" aria-label="View ${p.name}"><img src="${photo(p.image)}" alt="Illustrative accommodation photograph for ${p.name}" loading="lazy"></a><span class="pill">${p.tag}</span><button class="heart ${saved.includes(p.id)?'saved':''}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${p.name}" onclick="save(${p.id},this)">${saved.includes(p.id)?'♥':'♡'}</button></div><div class="property-body"><span class="location">⌾ ${p.location} <span style="float:right">${p.type==='Premium Hotels & Resorts'?'Resort':p.type}</span></span><h3><a href="#/stay/${p.id}">${p.name}</a></h3><div class="amenities">${p.amenities.slice(0,3).map(a=>`<span>${a==='Wi-Fi'?'⌁':a==='Parking'?'Ⓟ':'❋'} ${a==='Air conditioning'?'AC':a}</span>`).join('')}</div><div class="price-row"><div><span class="price">${money(p.price)} <small>/ night</small></span><span class="sample">AI illustration · Sample price</span></div><a class="btn outline small" href="#/stay/${p.id}">View stay ↗</a></div></div></article>`}
function save(id,button){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];localStorage.setItem('mks-saved',JSON.stringify(saved));button.classList.toggle('saved');button.textContent=saved.includes(id)?'♥':'♡';toast(saved.includes(id)?'Stay saved on this device.':'Stay removed from saved stays.')}
function home(){return `<section class="hero"><div class="container hero-content"><div class="eyebrow">Nashik · Trimbakeshwar · Kumbh 2027</div><h1>A sacred journey.<br>A place to <em>belong.</em></h1><p>Find your perfect stay for Nashik Kumbh 2027.<br>From peaceful homestays to thoughtfully chosen hotels, make room for what matters.</p><div class="hero-notes"><span>✧ Stays for every traveller</span><span>⌾ Close to your journey</span><span>♡ Local hospitality</span></div></div></section><div class="container search-wrap"><div class="search-box"><div class="search-caption">Your journey begins with a good stay.</div>${searchForm()}</div><div class="trust-strip"><span>✓ Thoughtfully selected stays</span><span>◇ Clear prices, no surprises</span><span>♧ Local knowledge & care</span><span>◷ Here when you need us</span></div></div><section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">Find your kind of comfort</div><h2>A stay for every journey.</h2><p>Simple or special, solo or together. There's a place for you.</p></div><a class="text-link" href="#/stays">Explore all stays ↗</a></div><div class="categories">${categories.map((c,i)=>`<button class="category" onclick="categorySearch('${c}')"><img src="${photo([images.room,images.resort,images.home,images.hotel,images.tent][i],500)}" alt="${c}" loading="lazy"><div><h3>${c==='Premium Hotels & Resorts'?'Hotels & Resorts':c}</h3><small>${['Comfort within reach','A little extra comfort','A home away from home','Simple stays, peaceful hearts','Closer to the experience'][i]} ↗</small></div></button>`).join('')}</div></div></section><section class="section tinted"><div class="container"><div class="section-heading"><div><div class="eyebrow">Places you'll love coming back to</div><h2>Stay a little closer.</h2><p>A few favourites to inspire your Kumbh journey.</p></div><a class="text-link" href="#/stays">View all properties ↗</a></div><div class="properties">${properties.slice(0,3).map(card).join('')}</div><p class="notice mt">Illustrative listings and photography · Sample prices · Not available for real booking.</p></div></section><section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">Discover the neighbourhood</div><h2>Where will your journey take you?</h2><p>Find your base, from the heart of the city to the foothills of Trimbak.</p></div></div><div class="locations">${locations.slice(0,4).map((l,i)=>`<button class="place" onclick="locationSearch('${l}')"><img src="${photo([images.river,images.temple,images.river,images.hotel][i],700)}" alt="Illustrative view for ${l}" loading="lazy"><strong>${l==='Panchavati / Ramkund'?'Panchavati & Ramkund':l}</strong><small>${['The energy of the city','At the foothills of faith','By the sacred Godavari','Well connected, easy to reach'][i]} ↗</small></button>`).join('')}</div></div></section><section class="section"><div class="container"><div class="center"><div class="eyebrow">A little peace of mind</div><h2 class="mt">You focus on the journey.<br>We'll help with the stay.</h2></div><div class="why">${[['♧','Thoughtful verification','Property verification is part of our planned launch process.'],['◇','Transparent pricing','See your room price and booking summary before you continue.'],['⌁','Simple booking','A clear path from finding your stay to your booking confirmation.'],['♡','Local care, always','A dedicated support space for questions, families and group stays.']].map(x=>`<div><div class="icon">${x[0]}</div><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></div></section><section class="section"><div class="container"><div class="partner"><div class="partner-copy"><div class="eyebrow">For hosts with heart</div><h2>Your space. Their journey.<br>A meaningful connection.</h2><p>Have a hotel, homestay or accommodation in Nashik?<br>Welcome travellers and grow with MahakumbhStays.</p><a href="#/owner" class="btn mt">List your property ↗</a></div><img src="${photo(images.room)}" alt="Welcoming room with warm natural light" loading="lazy"></div>${demo}<div class="support-line"><div><h3>Travelling together?</h3><p class="notice">Family gatherings, pilgrim groups, or something a little bigger.</p></div><a class="text-link" href="#/support">Let's plan your stay ↗</a></div></div></section>`}
function categorySearch(c){Object.assign(state,{type:c,page:1});goToStays()}function locationSearch(l){Object.assign(state,{destination:l,page:1});goToStays()}function go(path){if(location.hash==='#'+path)render();else location.hash=path;window.scrollTo(0,0)}
function listingLandmark(property){
    return property.landmark || (property.location==='Trimbakeshwar'?'Trimbakeshwar temple':'Ramkund');
}
function staysHref(overrides={}){
    const values={...state,...overrides};
    const params=new URLSearchParams();
    for(const key of Object.keys(searchDefaults)){
        if(key==='guests')continue;
        const value=values[key];
        if(Array.isArray(value)){value.forEach(item=>params.append(key,item));continue}
        if(value!=='' && (value!==searchDefaults[key] || ['checkin','checkout','adults','children','rooms','destination','type'].includes(key)))params.set(key,value);
    }
    return '#/stays?'+params;
}
function goToStays(){go(staysHref().slice(1))}
function readStaySearch(){
    Object.assign(state,parseStaySearch(new URLSearchParams(location.hash.split('?')[1])));
}
function results(){return '<div class="container section" role="status">Loading stays&hellip;</div>'}
function nights(){return Math.max(1,Math.round((new Date(state.checkout)-new Date(state.checkin))/86400000))}function nightly(){return selected.price+(roomIndex?1200:0)}function subtotal(){return nightly()*nights()*state.rooms}function tax(){return Math.round(subtotal()*.12)}
function detail(id){selected=properties.find(p=>p.id===+id);if(!selected)return '<div class="container section"><h1>Stay not found</h1><a href="#/stays">Back to stays</a></div>';let p=selected;return `<div class="container"><div class="page-head"><div class="breadcrumb"><a href="#/">Home</a> / <a href="#/stays">Explore stays</a> / ${p.name}</div><div class="details-title"><div><span class="eyebrow">${p.type}</span><h1>${p.name}</h1><span class="location">⌾ ${p.location} · Illustrative address, Nashik district, Maharashtra</span></div><button class="btn outline" onclick="save(${p.id},this)">${saved.includes(p.id)?'♥':'♡'}</button></div></div><div class="gallery"><img src="${photo(p.image,1400)}" alt="Illustrative property exterior"><div><img src="${photo(images.room,650)}" alt="Illustrative bedroom"><img src="${photo(images.bed,650)}" alt="Illustrative room interior"></div></div>${demo}<div class="detail-layout"><div><h2 class="mt">A restful pause in your journey.</h2><p class="notice">Settle into a welcoming ${p.type.toLowerCase()} experience in ${p.location}. With room to unwind and thoughtful everyday comforts, this sample stay offers a peaceful base for exploring Nashik and Trimbakeshwar.</p><div class="amenity-grid">${p.amenities.map(a=>`<span>✓ ${a}</span>`).join('')}<span>✓ Up to ${p.capacity} guests per room</span><span>✓ Family friendly</span></div><div class="detail-section"><h2>Choose your room</h2>${['Comfort Room','Family Suite'].map((r,i)=>`<div class="room"><div><h3>${r}</h3><p>${i?'Extra living space · ':''}Up to ${p.capacity} guests · Attached bathroom</p><p>${money(p.price+(i?1200:0))} / night · Live availability unconfirmed</p></div><button class="btn ${roomIndex===i?'green':'outline'} small" onclick="roomIndex=${i};render()">${roomIndex===i?'Selected ✓':'Select room'}</button></div>`).join('')}</div><div class="detail-section"><h2>Good to know</h2><p>Check-in: 2:00 PM · Check-out: 11:00 AM<br>Please carry a valid government photo ID. Quiet hours: 10:00 PM–7:00 AM. No smoking inside rooms. Contact the host before bringing pets.</p><h3>Sample cancellation policy</h3><p>Cancel without a room charge up to 7 days before arrival. Later cancellations may incur the first night's room charge. This is illustrative only; no real booking exists.</p></div><div class="detail-section"><h2>Around your stay</h2><div class="map-panel">⌾ ${p.location}<p class="notice">${p.distance} km from the selected local landmark (sample).</p><a class="text-link" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(p.location+' Nashik Maharashtra')}">Explore the area on Google Maps ↗</a></div></div></div><aside class="panel booking-panel"><span class="price">${money(nightly())} <small>/ night</small></span><p class="notice">${roomIndex?'Family Suite':'Comfort Room'} · Live availability unconfirmed</p><form onsubmit="bookStart(event)"><div class="field"><label for="d-in">Check-in</label><input id="d-in" type="date" name="checkin" value="${state.checkin}" required></div><div class="field"><label for="d-out">Check-out</label><input id="d-out" type="date" name="checkout" value="${state.checkout}" required></div><div class="field"><label for="d-guests">Guests</label><input id="d-guests" type="number" min="1" max="${p.capacity*4}" name="guests" value="${state.guests}" required></div><div class="field"><label for="d-rooms">Rooms</label><input id="d-rooms" type="number" min="1" max="4" name="rooms" value="${state.rooms}" required></div><button class="btn" type="submit">Continue to booking →</button><p class="notice center mt">You won't be charged.<br>This is a frontend demonstration.</p></form></aside></div></div>`}
function bookStart(e){e.preventDefault();let f=new FormData(e.target);if(f.get('checkout')<=f.get('checkin'))return toast('Check-out must be after check-in.');if(+f.get('guests')>selected.capacity*+f.get('rooms'))return toast('Please add more rooms for this number of guests.');Object.assign(state,{checkin:f.get('checkin'),checkout:f.get('checkout'),guests:+f.get('guests'),rooms:+f.get('rooms')});go('/checkout')}
function summary(){return `<aside class="panel" style="align-self:start"><img class="summary-img" src="${photo(selected.image,650)}" alt="Illustrative stay"><h3>${selected.name}</h3><p class="notice">${selected.location} · ${roomIndex?'Family Suite':'Comfort Room'}<br>${state.checkin} → ${state.checkout}<br>${state.guests} guests · ${state.rooms} room(s) · ${nights()} nights</p><div class="summary-line"><span>${money(nightly())} × ${nights()} nights × ${state.rooms} rooms</span><span>${money(subtotal())}</span></div><div class="summary-line"><span>Illustrative tax (12%)</span><span>${money(tax())}</span></div><div class="summary-line total"><span>Demo total</span><span>${money(subtotal()+tax())}</span></div><p class="notice">The tax rate is a placeholder for this demonstration. No payment will be collected.</p></aside>`}
function steps(n){return `<div class="steps">${['1. Guest details','2. Review booking','3. Demo payment','4. Confirmation'].map((s,i)=>`<span class="${i===n?'active':''}">${s}</span>`).join('')}</div>`}
function checkout(stage){return `<div class="container"><div class="page-head"><div class="breadcrumb"><a href="#/stay/${selected.id}">← Back to your stay</a></div><h1>${stage==='review'?'Everything look right?':stage==='payment'?'One last step.':'Make yourself at home.'}</h1>${steps(stage==='review'?1:stage==='payment'?2:0)}</div>${demo}<div class="checkout"><div class="panel">${stage==='review'?`<h2>Review your demo booking</h2><p>${escapeHtml(guest.name||'Guest')}<br>${escapeHtml(guest.email||'')}<br>${escapeHtml(guest.phone||'')}</p><p class="notice">Arrival note: ${escapeHtml(guest.note||'No special requests')}</p><div class="detail-section"><h3>Cancellation terms</h3><p class="notice">Free cancellation up to 7 days before arrival. Within 7 days, the sample first-night charge applies. No money is collected in this demo.</p></div><button class="btn" onclick="go('/payment')">Continue to demo payment →</button> <button class="text-link" onclick="go('/checkout')">Edit details</button>`:stage==='payment'?`<h2>Simulated payment</h2><p class="notice">Choose a sample payment method. Do not enter real payment information.</p><form onsubmit="confirmBooking(event)">${['UPI','Debit / credit card','Net banking'].map((x,i)=>`<label class="room"><span>${x}</span><input type="radio" name="method" value="${x}" ${i===0?'checked':''}></label>`).join('')}<label class="check-label"><input type="checkbox" required><span>I understand this creates a demonstration confirmation only.</span></label><button class="btn wide">Simulate successful payment · ${money(subtotal()+tax())}</button><button type="button" class="btn outline wide mt" onclick="toast('Simulated payment failed. You can retry safely.')">Try payment failure</button></form>`:`<h2>Who's joining the journey?</h2><p class="notice">Use sample details for this frontend demonstration.</p><form onsubmit="guestSubmit(event)"><div class="form-grid">${[['name','Full name','text'],['email','Email address','email'],['phone','Mobile number','tel']].map(([n,l,t])=>`<div class="form-field ${n==='name'?'full':''}"><label for="guest-${n}">${l}</label><input class="input" id="guest-${n}" type="${t}" name="${n}" value="${escapeHtml(guest[n]||'')}" ${n==='phone'?'pattern="[+0-9 ()-]{8,18}"':''} required></div>`).join('')}<div class="form-field full"><label for="guest-note">Special requests (optional)</label><textarea class="input" id="guest-note" name="note" placeholder="Accessibility needs, arrival time, or anything else…">${escapeHtml(guest.note||'')}</textarea></div></div><label class="check-label"><input type="checkbox" required><span>I have read the sample <a class="text-link" href="#/policy/terms" target="_blank">terms</a> and cancellation policy.</span></label><button class="btn">Review booking →</button></form>`}</div>${summary()}</div></div>`}
function guestSubmit(e){e.preventDefault();guest=Object.fromEntries(new FormData(e.target));go('/review')}
function confirmBooking(e){e.preventDefault();booking={id:'DEMO-'+Date.now().toString().slice(-7),method:new FormData(e.target).get('method'),property:selected.name,date:state.checkin,total:subtotal()+tax()};sessionStorage.setItem('mks-booking',JSON.stringify({...booking,guest:guest.name}));go('/confirmation')}
function confirmation(){if(!booking)return `<div class="container section"><h1>No demo confirmation yet.</h1><a class="btn" href="#/stays">Explore stays</a></div>`;return `<div class="container"><div class="success panel"><div class="success-mark">✓</div><span class="eyebrow">Your demo journey is ready</span><h1 class="serif mt">A little closer to your sacred journey.</h1><p>Thank you, ${escapeHtml(guest.name||'traveller')}. Your simulated booking is complete.</p>${demo}<h3>${booking.id}</h3><p class="notice">${selected.name}<br>${state.checkin} → ${state.checkout}<br>${state.guests} guests · ${state.rooms} rooms<br>Demo total: ${money(booking.total)}</p><p class="notice">No room has been reserved. No payment was collected.<br>No email or WhatsApp notification has been sent.</p><button class="btn" onclick="downloadVoucher()">Download demo voucher ↓</button> <a class="btn outline mt" href="#/stays">Explore more stays</a></div></div>`}
function downloadVoucher(){let text=`MAHAKUMBHSTAYS — DEMONSTRATION VOUCHER\nNOT A REAL RESERVATION\n\n${booking.id}\nGuest: ${guest.name}\nStay: ${selected.name}\nRoom: ${roomIndex?'Family Suite':'Comfort Room'}\nDates: ${state.checkin} to ${state.checkout}\nGuests: ${state.guests}; Rooms: ${state.rooms}\nIllustrative total: INR ${booking.total}\n\nNo payment collected. No room reserved.`;let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download=booking.id+'-voucher.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function dashboard(admin=false){const tabs=admin?['Overview','Property approvals','Bookings','Inventory','Owners','Commissions','Payments & refunds','Customers']:['Overview','My properties','Reservations','Room inventory','Rates & settlements','Profile'];if(!tabs.includes(dashTab))dashTab='Overview';return `<div class="container"><div class="dashboard"><aside class="sidebar">${brand}${tabs.map(t=>`<button class="side-link ${dashTab===t?'active':''}" onclick="dashTab='${t}';render()">${t}</button>`).join('')}<div class="menu-note">${admin?'Administrator':'Property partner'} demo<br>No authentication or live data.</div></aside><section><span class="eyebrow">${admin?'Platform administration':'Your partner space'}</span><h1 class="serif">${dashTab==='Overview'?(admin?'A view of every journey.':'Welcome back, partner.'):dashTab}</h1>${demo}${dashTab==='Overview'?`<div class="stats">${(admin?[['Demo properties','10'],['Sample reservations','24'],['Illustrative booking value','₹1.48L']]:[['Your sample properties','2'],['Demo reservations','8'],['Illustrative earnings','₹24,640']]).map(x=>`<div class="stat"><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div><div class="panel"><h3>Recent sample reservations</h3>${reservationTable()}</div><div class="panel mt"><h3>${admin?'Platform readiness':'Ready to welcome your next guest?'}</h3><p class="notice">${admin?'Property approvals, commission settings and inventory controls are available from the menu. All changes are browser-only demonstrations.':'Keep your room details and availability up to date. Submit new properties for sample administrative review.'}</p><button class="btn" onclick="dashTab='${admin?'Property approvals':'My properties'}';render()">${admin?'Review properties':'Manage properties'} →</button></div>`:dashboardTab(admin)}</section></div></div>`}
function reservationTable(){return `<div class="table-wrap"><table><thead><tr><th>Booking</th><th>Guest</th><th>Stay</th><th>Arrival</th><th>Amount</th><th>Status</th></tr></thead><tbody>${[['DEMO-1024','Aarav Shah',properties[0].name,'15 Jul 2027','₹9,408','Confirmed'],['DEMO-1025','Meera Patil',properties[1].name,'18 Jul 2027','₹6,272','Confirmed'],['DEMO-1026','Vikram Rao',properties[2].name,'20 Jul 2027','₹4,032','Pending']].map(x=>`<tr>${x.map((v,i)=>`<td>${i===5?`<span class="status ${v==='Pending'?'pending':''}">${v}</span>`:v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function dashboardTab(admin){if(['Bookings','Reservations'].includes(dashTab))return `<div class="panel">${reservationTable()}</div>`;if(['Property approvals','My properties'].includes(dashTab))return `<div class="panel"><div class="section-heading"><h3>${admin?'Properties awaiting review':'Your sample properties'}</h3>${admin?'':'<button class="btn small" onclick="propertyForm()">+ Add property</button>'}</div><div class="table-wrap"><table><thead><tr><th>Property</th><th>Location</th><th>Status</th><th>Action</th></tr></thead><tbody>${[...properties.slice(0,admin?4:2),...ownerDrafts].map((p,i)=>`<tr><td>${escapeHtml(p.name)}</td><td>${escapeHtml(p.location)}</td><td><span class="status pending" id="status-${i}">${admin||p.draft?'Pending review':'Demo approved'}</span></td><td>${admin?`<button class="text-link" onclick="document.getElementById('status-${i}').textContent='Demo approved';toast('Approved in this preview only.')">Approve</button>`:`<button class="text-link" onclick="propertyForm(${p.id||0})">Edit</button>`}</td></tr>`).join('')}</tbody></table></div></div>`;if(['Inventory','Room inventory'].includes(dashTab))return `<div class="panel"><h3>Sample daily inventory</h3><form onsubmit="event.preventDefault();toast('Inventory updated in this preview only.')"><div class="form-grid"><div class="form-field"><label>Date</label><input class="input" type="date" value="2027-07-15" required></div><div class="form-field"><label>Room type</label><select class="input"><option>Comfort Room</option><option>Family Suite</option></select></div><div class="form-field"><label>Rooms available</label><input class="input" type="number" min="0" value="5" required></div></div><button class="btn mt">Save sample inventory</button></form></div>`;if(['Commissions','Rates & settlements'].includes(dashTab))return `<div class="panel"><h3>${admin?'Property-specific commission':'Rates and illustrative settlements'}</h3><form onsubmit="event.preventDefault();toast('Sample settings saved in this preview.')"><div class="form-grid"><div class="form-field"><label>Property</label><select class="input">${properties.slice(0,admin?10:2).map(p=>`<option>${p.name}</option>`).join('')}</select></div><div class="form-field"><label>${admin?'Commission (%)':'Nightly rate (₹)'}</label><input class="input" type="number" min="0" max="${admin?100:100000}" value="${admin?12:4200}" required></div></div><button class="btn mt">Save sample settings</button></form><p class="notice mt">Example: ₹10,000 booking − ₹1,200 platform commission = ₹8,800 property share before tax and adjustments. No actual settlement takes place.</p></div>`;if(dashTab==='Payments & refunds')return `<div class="panel"><h3>Sample refund requests</h3><div class="room"><div><h3>DEMO-1023 · ₹4,032</h3><p>Customer cancellation · No actual payment</p></div><button class="btn small" onclick="this.textContent='Demo processed';this.disabled=true;toast('Refund simulated. No money moved.')">Simulate refund</button></div></div>`;if(dashTab==='Profile')return `<div class="panel"><h3>Partner profile</h3><form onsubmit="event.preventDefault();toast('Profile updated in this preview.')"><div class="form-grid"><div class="form-field"><label>Name</label><input class="input" value="Demo Partner" required></div><div class="form-field"><label>Email</label><input class="input" type="email" value="partner@example.com" required></div></div><button class="btn mt">Save profile</button></form></div>`;return `<div class="panel"><h3>Sample ${dashTab.toLowerCase()}</h3><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Status</th></tr></thead><tbody>${(dashTab==='Owners'?['Demo Host One','Demo Host Two']:['Aarav Shah','Meera Patil']).map((x,i)=>`<tr><td>${x}</td><td>demo${i+1}@example.com</td><td><span class="status">Sample active</span></td></tr>`).join('')}</tbody></table></div></div>`}
function modal(content){$('#modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="Dialog"><button class="modal-close" aria-label="Close dialog" onclick="closeModal()">×</button>${content}</section></div>`;$('#modal-root input, #modal-root button')?.focus()}function closeModal(){$('#modal-root').innerHTML=''}document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function propertyForm(id,initialType){let p=properties.find(p=>p.id===id)||ownerDrafts.find(p=>p.id===id)||{};modal(`<h2>${id?'Edit':'List'} your property</h2><p class="notice">Saved as a draft on this device only. Listings require approval before real bookings.</p><form onsubmit="saveProperty(event,${id||0})"><div class="form-field"><label for="property-name">Property name</label><input id="property-name" class="input" name="name" value="${escapeHtml(p.name||'')}" required></div><div class="form-field"><label for="property-location">Location</label><select id="property-location" class="input" name="location">${locations.map(l=>`<option ${p.location===l?'selected':''}>${l}</option>`).join('')}</select></div><div class="form-field"><label>Accommodation type</label><select class="input" name="type">${categories.map(c=>`<option ${(p.type||initialType)===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label>Nightly rate (₹)</label><input class="input" type="number" name="price" min="1" value="${p.price||1800}" required></div><div class="form-field"><label>Property description</label><textarea class="input" name="description">${escapeHtml(p.description||'')}</textarea></div><div class="form-field"><label>Property photographs (local preview only)</label><input type="file" accept="image/*" multiple onchange="document.getElementById('upload-note').textContent=this.files.length+' photo(s) selected for preview'"><p class="notice" id="upload-note">No files are uploaded to a server.</p></div><button class="btn">Save draft for review</button></form>`)}
function saveProperty(e,id){e.preventDefault();let draft={...Object.fromEntries(new FormData(e.target)),id:id||Date.now(),draft:true};let existing=ownerDrafts.findIndex(p=>p.id===id);if(existing>=0)ownerDrafts[existing]=draft;else ownerDrafts.push(draft);localStorage.setItem('mks-drafts',JSON.stringify(ownerDrafts));closeModal();render();toast('Property draft saved on this device. Pending sample review.')}
function login(){modal(`<h2>Welcome to your journey.</h2><p class="notice">Demo access only. No real OTP will be sent.</p><form onsubmit="event.preventDefault();demoLogin()"><div class="form-field"><label for="login-phone">Mobile number</label><input class="input" id="login-phone" type="tel" pattern="[+0-9 ()-]{8,18}" placeholder="Use a sample phone number" required></div><button class="btn wide">Continue to demo sign in →</button></form>`)}function demoLogin(){modal(`<h2>Choose your demo space.</h2><p class="notice">Production sign-in and access permissions will be added with the backend.</p><a class="btn wide" href="#/account" onclick="closeModal()">Customer demo</a><a class="btn outline wide mt" href="#/owner" onclick="closeModal()">Hotel partner portal</a><a class="text-link mt" style="display:block" href="#/admin" onclick="closeModal()">Administrator demo →</a>`)}
function support(){return `<div class="container section"><span class="eyebrow">A little help along the way</span><h1 class="serif" style="font-size:44px">Let's make your journey easier.</h1><div class="checkout"><div class="panel"><h2>Tell us what you need.</h2><p><a class="text-link" href="#/group-stays">Request accommodation for a group of 10 or more &rarr;</a></p><form onsubmit="submitPublicEnquiry(event)"><div class="form-grid"><div class="form-field"><label for="enquiry-name">Your name</label><input id="enquiry-name" class="input" name="name" maxlength="120" required></div><div class="form-field"><label for="enquiry-email">Email</label><input id="enquiry-email" class="input" name="email" type="email" maxlength="254" required></div><div class="form-field"><label for="enquiry-type">Enquiry type</label><select id="enquiry-type" class="input" name="type"><option>Booking help</option><option>Property partnership</option><option>Accessibility needs</option></select></div><div class="form-field"><label for="enquiry-group">Group size</label><input id="enquiry-group" class="input" name="size" type="number" min="1" value="10" required></div><div class="form-field full"><label for="enquiry-message">How can we help?</label><textarea id="enquiry-message" class="input" name="details" maxlength="2400" required></textarea></div></div><button class="btn mt">Submit enquiry &rarr;</button><p class="notice mt" role="status"></p></form></div><aside class="panel"><h2>Good to know</h2>${[['Can I book a real room?','Approved properties can accept reservations when live inventory and online payment are available. Illustrative listings are marked as previews.'],['Are the prices final?','For bookable listings, the checkout shows the server-calculated nightly rates and taxes before you place a hold.'],['Can I list my property?','Register as a rental host and submit your property for verification.'],['Which languages are available?','This first frontend is in English. Hindi and Marathi translations are planned for a later phase.']].map(([q,a])=>`<details class="detail-section"><summary>${q}</summary><p class="notice mt">${a}</p></details>`).join('')}</aside></div></div>`}
function account(){let last=JSON.parse(sessionStorage.getItem('mks-booking')||'null');return `<div class="container section"><span class="eyebrow">Customer demo</span><h1 class="serif" style="font-size:40px">Your journeys, in one place.</h1>${demo}<h2>Booking history</h2><div class="panel">${last?`<h3>${escapeHtml(last.property)}</h3><p>${last.id} · ${last.date} · ${money(last.total)}</p><span class="status">Simulated confirmation</span>`:'<p class="notice">Complete the demo booking journey to see a sample confirmation here.</p><a class="btn" href="#/stays">Find a stay</a>'}</div><h2 class="mt">Your saved stays</h2><div class="properties">${properties.filter(p=>saved.includes(p.id)).map(card).join('')||'<p class="notice">Tap the heart on a property to save it on this device.</p>'}</div></div>`}
function policy(type){return `<div class="container section" style="max-width:850px"><span class="eyebrow">Prototype information</span><h1 class="serif" style="font-size:40px">${type==='privacy'?'Privacy policy':type==='cancellation'?'Cancellation policy':'Terms & conditions'}</h1>${demo}<div class="panel">${type==='privacy'?'<h3>Your information in this preview</h3><p>This prototype has no account service or booking database. Saved stays and property drafts are stored in your browser on this device. The latest demo booking summary is stored for this browser session. Guest details are used only to display the simulated checkout and voucher.</p><p>External image and font providers receive normal browser requests. Do not enter sensitive personal or payment information.</p>':type==='cancellation'?'<h3>Sample cancellation terms</h3><p>The illustrated policy allows cancellation up to 7 days before arrival without a room charge. Later cancellations illustrate a first-night room charge. No real reservation, charge, cancellation, or refund takes place in this preview.</p>':'<h3>Use of this prototype</h3><p>All accommodation names, listings, reviews, rates and availability are sample data for reviewing the frontend. Photographs are illustrative and do not verify an actual property. Submitting a form does not create a real booking or send an enquiry.</p><p>Production terms, property agreements, payment arrangements and policies must be prepared before public booking operations begin.</p>'}<button class="btn outline mt" onclick="history.back()">← Go back</button></div></div>`}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function render(){let path=(location.hash.slice(1).split('?')[0]||'/').split('/').filter(Boolean),page=path[0],content;if(page==='stays'){readStaySearch();content=results()}else if(['cabs','cab-trip','restaurants','restaurant'].includes(page))content='<section class="container section" id="services-root">Loading&hellip;</section>';else if(page==='stay')content=new URLSearchParams(location.hash.split('?')[1]).get('catalog')==='live'?'<div id="live-stay" class="container section" role="status">Loading property&hellip;</div>':detail(path[1]);else if(['checkout','review','payment'].includes(page))content=checkout(page);else if(page==='reservation')content='<div class="container section" id="reservation-status">Loading reservation&hellip;</div>';else if(page==='confirmation')content=confirmation();else if(['admin','rental-host','hotel-partner','cab-partner','owner'].includes(page))content='<section class="container section" id="operations-root">Loading&hellip;</section>';else if(page==='group-stays'||page==='group-quote')content='<section class="container section" id="bulk-root">Loading&hellip;</section>';else if(page==='support')content=support();else if(page==='guide')content='<div class="container section" id="pilgrim-guide">Loading&hellip;</div>';else if(page==='account')content=account();else if(page==='policy')content=policy(path[1]);else content=home();$('#app').innerHTML=header()+`<main id="main-content" tabindex="-1">${content}</main>`+footer();document.title=page?`${page==='stay'?(document.getElementById('live-stay')?'Stay':selected?.name||'Stay'):page[0].toUpperCase()+page.slice(1)} · MahakumbhStays`:'MahakumbhStays — Your stay for every sacred journey'}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});





